UPDATE public.ai_knowledge SET content='New enquiries share name, mobile and email first, then what they are looking for (membership, personal training, recovery, classes or just looking), the plan that interests them and their main fitness goal. On WhatsApp ask naturally, one item at a time, only after answering their question; never re-ask anything already known. If they ignore a request twice, stop asking and keep being useful.', updated_at=now() WHERE id='ff1322cd-9bb5-45c0-8fe1-3196818c0088';